function calculateAqi(value, vMapping, aMapping) {
    var bpLow = null;
    var bpHigh = null;
    var aqiLow = null;
    var aqiHigh = null;
    for (var i = 0; i < vMapping.length; i++) {
        bpLow = vMapping[i].low;
        bpHigh = vMapping[i].high;
        if (value >= bpLow && value <= bpHigh) {
            aqiLow = aMapping[i].low;
            aqiHigh = aMapping[i].high;
            return (int)(((aqiHigh - aqiLow) / (bpHigh - bpLow)) * (value - bpLow) + aqiLow);
        }
        if (i == vMapping.length - 1 && value > bpHigh) {
            return aMapping[i].high;
        }
    }
    return null;
}

